const d = $input.first().json;
const c = d.current || {};
const day = d.daily || {};
const max = Array.isArray(day.temperature_2m_max) ? day.temperature_2m_max[0] : '--';
const min = Array.isArray(day.temperature_2m_min) ? day.temperature_2m_min[0] : '--';
const lluvia = Array.isArray(day.precipitation_probability_max) ? day.precipitation_probability_max[0] : '--';
const codes = {0:'Despejado',1:'Mayormente despejado',2:'Parcialmente nublado',3:'Nublado',45:'Niebla',51:'Llovizna',61:'Lluvia ligera',63:'Lluvia',65:'Lluvia fuerte',71:'Nieve',80:'Chubascos',95:'Tormenta'};
const estado = codes[c.weather_code] || 'Variable';
const fecha = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz', weekday: 'long', day: 'numeric', month: 'long' });
const tips = [
  'Sugiere el plato del dia por WhatsApp a tus clientes frecuentes.',
  'Confirma por WhatsApp las reservas de hoy: reduce las mesas vacias.',
  'Sube 1 foto del plato estrella a Google: mas clics que cualquier texto.',
  'Pide resena a la ultima mesa contenta: sube tu ranking en Google.',
  'Revisa el stock de tus 3 platos mas pedidos antes del mediodia.'
];
const tip = tips[new Date().getDate() % tips.length];
let msg = '🍣 <b>Buen dia, New Sakura — ' + fecha + '</b>\n\n';
msg += '🌡️ <b>Clima La Paz (Calacoto):</b> ' + (c.temperature_2m ?? '--') + '°C, ' + estado + '\n';
msg += '   Maxima ' + max + '°C · Minima ' + min + '°C · Prob. lluvia ' + lluvia + '%\n';
msg += (lluvia >= 50 ? '   ⚠️ Alta chance de lluvia: prepara el delivery y mesas internas.\n' : '   ✅ Buen dia para la terraza.\n');
msg += '\n📋 <b>Reservas de hoy:</b> (se conecta a tu agenda/WhatsApp)\n   • 13:00 — Mesa 4, 6 personas\n   • 20:30 — Mesa 2, aniversario\n\n';
msg += '💡 <b>Tip del dia:</b> ' + tip + '\n\n';
msg += '🤖 <i>Asistente ONIA para New Sakura — llega solo cada manana. Esto es un demo; con tus datos reales muestra reservas, pedidos y ventas.</i>';
return [{ json: { mensaje: msg } }];
